// Port métier, dans le module domaine
public interface ShippingGateway {
    ShippingQuote quote(Address destination, Parcel parcel);
}

// Service métier, ne dépend que du port
@Service
public class ShippingService {
    private final ShippingGateway shippingGateway;

    public ShippingService(ShippingGateway shippingGateway) {
        this.shippingGateway = shippingGateway;
    }

    public ShippingQuote cheapestQuote(Address destination, Parcel parcel) {
        return shippingGateway.quote(destination, parcel);
    }
}

// Adaptateur d'infrastructure, dans le module persistence
@Component
public class JpaShippingGateway implements ShippingGateway {
    private final ShippingRateRepository repository;

    public JpaShippingGateway(ShippingRateRepository repository) {
        this.repository = repository;
    }

    @Override
    public ShippingQuote quote(Address destination, Parcel parcel) {
        return repository.findRate(destination.zipCode()).toQuote(parcel);
    }
}

