import java.util.ArrayList;
import java.util.List;

record Order(Integer id, List<String> items) {}

interface OrderRepository {
    Order save(Order order);

    int count();
}

class InMemoryOrderRepository implements OrderRepository {
    private final List<Order> stored = new ArrayList<>();

    public Order save(Order order) {
        // TODO 1 : attribue l'identifiant stored.size() + 1, mémorise la commande et retourne-la
        return order;
    }

    public int count() {
        return stored.size();
    }
}

class OrderService {
    private final OrderRepository repository;

    OrderService(OrderRepository repository) {
        this.repository = repository;
    }

    Order create(List<String> items) {
        // TODO 2 : refuse une liste vide avec new IllegalArgumentException("la commande doit contenir au moins un article")
        // TODO 3 : enregistre la commande (id null) via le port et retourne le résultat
        return new Order(null, items);
    }
}

public class Main {
    public static void main(String[] args) {
        var repository = new InMemoryOrderRepository();
        var service = new OrderService(repository);

        var order = service.create(List.of("clavier", "souris", "écran"));
        System.out.println("Commande " + order.id() + " créée: " + order.items().size() + " articles");
        try {
            service.create(List.of());
        } catch (IllegalArgumentException error) {
            System.out.println("Refusée: " + error.getMessage());
        }
        System.out.println("Persistées: " + repository.count());
    }
}

